{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Prednisolone, the closest analogue differing mainly by the absence of the 6-chloro substituent, has an absolute oral bioavailability of 0.92 for tablets versus IV prednisolone, indicating essentially complete systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Methylprednisolone, another close corticosteroid analogue, delivers 82.4% of an oral tablet dose to the systemic circulation relative to IV, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Hydrocortisone, a structurally related corticosteroid, has an absolute oral bioavailability of 95.9% after oral versus IV administration, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Dexamethasone, a halogenated corticosteroid relevant to the chloro-substituted query, has a mean absolute oral bioavailability of 60.7% with a range of 33.7-89.2%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Loteprednol etabonate has very low oral bioavailability, but this is attributed to its ester prodrug nature and extensive presystemic hydrolysis, which does not transfer to the non-ester query corticosteroid.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C43"],
      "claim": "Anecortave desacetate has low oral bioavailability in humans, but its structural differences and metabolic liability limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 6-chloro corticosteroid closely related to prednisolone. High-similarity analogues—prednisolone, methylprednisolone, hydrocortisone, and dexamethasone—consistently show absolute oral bioavailability well above 20%, mostly 55-100%. The few low-bioavailability analogues are structurally distant ester prodrugs or metabolically labile compounds whose low F mechanisms do not apply to the query. Therefore, the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for cloprednol itself; the prediction relies on close corticosteroid analogues.",
    "The specific effect of the 6-chloro substituent on first-pass metabolism, solubility, or transporter-mediated disposition is not directly measured.",
    "Low-bioavailability analogues such as loteprednol etabonate and anecortave desacetate are structurally distant and their low F mechanisms are unlikely to transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

